// moth extension for Pi (@earendil-works/pi-coding-agent 1.1-1.3): send the agent's final reply of each run to the
// local moth companion, show moth's reaction above the editor, and chat with it via /moth. Install: copy to
// ~/.pi/agent/extensions/moth.ts, or `pi -e /abs/path/moth.ts` (docs: extensions.md "Add it to Pi").
// Events (docs: extensions.md, json.md; types: packages/coding-agent/src/core/extensions/types.ts at v1.3.0):
//   agent_start  a low-level run begins: forget any older text, so a run without a reply posts nothing.
//   agent_end    `messages` = the messages generated by that run: remember the last assistant text in it. Retries,
//                overflow recovery or queued work can still follow, so we don't post yet.
//   agent_settled  "Pi will not continue automatically": post the remembered text unless `aborted` (Escape).
// Assistant messages with stopReason "error" / "aborted" are skipped; only `text` blocks count (no thinking).
// Session and label, so moth can tell several sessions apart: ctx.sessionManager.getSessionId() and the basename of
// ctx.cwd (ExtensionContext in types.d.ts), read from agent_settled's ctx.
// Posting is fire-and-forget: fetch with a 1 s timeout, never awaited, every rejection swallowed, nothing printed.
// Display (interactive only, ctx.hasUI): after posting, poll moth's lines (GET /api/says) every 0.5 s for up to
// WAIT_MS and put moth's newest line in a widget (ctx.ui.setWidget, above the editor). The poll asks only for moth's
// reactions to THIS session (`source=pi&session=<id>`, the id just posted), so with several agents running the
// widget never shows moth's reply to another one; without a session id there is nothing to show. The log cursor
// persists, so a reaction slower than WAIT_MS shows after the next run instead of being lost. Poll timers are unref'd, so a
// one-shot `pi -p` never waits on them. /moth <text> (pi.registerCommand) POSTs /api/chat, whose answer carries
// moth's reply once it has spoken (up to WAIT_MS). It stays out of the agent's context: Pi runs an extension
// command's handler and returns before any message is made, idle or mid-stream (dist/core/agent-session.js
// prompt() -> _tryExecuteExtensionCommand; interactive-mode.js routes streaming input through prompt() too), and
// the handler only calls ctx.ui (widget / notify). The typed line lands only in the editor's local up-arrow history.
// Agent and moth text is shown with terminal escape codes stripped (only our own lamp-yellow prefix is coloured).
// The display is OFF by default (moth's own setting `show_in_harness`, see moth/config.py): enabled() reads
// MOTH_SHOW_IN_HARNESS (1/0, on/off, true/false, yes/no), else "show_in_harness" in ~/.moth/config.json
// (MOTH_CONFIG_FILE overrides), on every turn, so `python -m moth config show_in_harness on|off` applies from the
// next turn without restarting Pi. Off: the reply is still posted (the desktop pet reacts), but there is no poll,
// no widget, and a widget shown earlier is cleared. /moth is registered either way (Pi registers commands at load,
// so it can't follow a live toggle): typing it is an explicit ask, so it always answers; with the setting off the
// reply comes as a one-off notice instead of the widget.
// Plain JS syntax on purpose: Pi loads it as TS via jiti, and `node --check` works on a .mjs copy.
// Env: MOTH_URL (default http://127.0.0.1:4747); the token is read from ~/.moth/token (MOTH_TOKEN_FILE overrides);
// MOTH_SHOW_IN_HARNESS / MOTH_CONFIG_FILE as above.
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const BASE = (process.env.MOTH_URL || "http://127.0.0.1:4747").replace(/\/+$/, "");
const MOTH = BASE + "/api/agent";
const TOKEN_FILE = process.env.MOTH_TOKEN_FILE || join(homedir(), ".moth", "token");
const WAIT_MS = 4000;
const ANSI = /\x1b\[[0-?]*[ -\/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)?|\x1b[@-_]|[\x00-\x08\x0b-\x1f\x7f-\x9f]/g;

function flag(v) {   // the same spellings as moth/config.py parse_bool; null = not a setting
  if (typeof v === "boolean") return v;
  if (typeof v !== "string") return null;
  const s = v.trim().toLowerCase();
  return ["1", "on", "true", "yes"].includes(s) ? true : ["0", "off", "false", "no"].includes(s) ? false : null;
}

export function enabled() {   // show moth's replies in Pi? env, else ~/.moth/config.json, else off. Read every turn.
  const env = flag(process.env.MOTH_SHOW_IN_HARNESS || "");
  if (env !== null) return env;
  try {
    const file = process.env.MOTH_CONFIG_FILE || join(homedir(), ".moth", "config.json");
    const v = flag((JSON.parse(readFileSync(file, "utf8")) || {}).show_in_harness);
    if (v !== null) return v;
  } catch (e) { /* no file / bad JSON: the default */ }
  return false;
}

function headers() {   // moth's per-install token, read on every post (moth may have made it after we loaded)
  let token = "";
  try { token = readFileSync(TOKEN_FILE, "utf8").trim(); } catch (e) { /* moth never ran: it will say 401 */ }
  return { "Content-Type": "application/json", "X-Moth-Token": token };
}

function labelOf(dir, session) {   // the project folder's name; without one, a short session id
  const name = String(dir || "").replace(/[\/\\]+$/, "").split(/[\/\\]/).pop();
  return name || String(session || "").slice(0, 8);
}

function body(text, source, session, label) {   // session / label only when known
  const b = { text, source };
  if (session) b.session = String(session);
  if (label) b.label = String(label);
  return JSON.stringify(b);
}

export function post(text, session, label) {
  try {
    fetch(MOTH, {
      method: "POST", headers: headers(), body: body(text, "pi", session, label),
      signal: AbortSignal.timeout(1000),
    }).catch(() => {});
  } catch (e) { /* no fetch / bad URL: drop it */ }
}

export function lastText(messages) {
  for (let i = (messages || []).length - 1; i >= 0; i--) {
    const m = messages[i];
    if (!m || m.role !== "assistant" || m.stopReason === "error" || m.stopReason === "aborted") continue;
    const parts = Array.isArray(m.content) ? m.content : [];
    const text = parts.filter((p) => p && p.type === "text" && typeof p.text === "string").map((p) => p.text).join("\n");
    if (text.trim()) return text;
  }
  return "";
}

const saysOf = (events) => (Array.isArray(events) ? events : [])
  .filter((e) => e && typeof e.say === "string" && e.say.trim()).map((e) => e.say);

async function getSays(since, epoch, session) {   // moth's own lines only: no token needed
  let q = epoch ? `since=${since}&epoch=${encodeURIComponent(epoch)}` : `since=${since}`;
  if (session) q += `&source=pi&session=${encodeURIComponent(session)}`;   // only moth's reactions to this session
  const r = await fetch(`${BASE}/api/says?${q}`, { signal: AbortSignal.timeout(1000) });
  const d = await r.json();
  if (!Array.isArray(d.events) || typeof d.next !== "number") throw new Error("not moth");
  return d;
}

function show(ctx, text) {   // false when there is no widget to put it in
  try {
    const flat = String(text).replace(ANSI, "").replace(/\s+/g, " ").trim();
    ctx.ui.setWidget("moth", [`\x1b[33mmoth>\x1b[0m ${flat.length > 300 ? flat.slice(0, 299) + "…" : flat}`]);
    return true;
  } catch (e) { return false; }
}

export default function (pi) {
  let last = "";
  let cursor = null;   // index into moth's log; null = not known yet
  let epoch = null;    // changes when moth restarts or the chat is reset: the server then sends the new log
  let run = 0;         // the newest poll wins
  let shown = false;   // our widget is on screen
  let wasOn = false;   // the setting at the last agent_start

  const start = (d) => { if (cursor === null) { cursor = d.next; epoch = d.epoch; } };
  // Baseline the log while the agent works, so the post that follows is after the cursor.
  const baseline = () => { if (cursor === null) getSays(1e9).then(start, () => {}); };

  const widget = (ctx, text) => { const ok = show(ctx, text); if (ok) shown = true; return ok; };

  // Setting off: stop any poll, forget the cursor (turning it back on starts fresh, never with an old line) and
  // take our widget down.
  function quiet(ctx) {
    cursor = null; epoch = null; run++;
    if (shown) { try { ctx.ui.setWidget("moth", undefined); shown = false; } catch (e) { /* no UI */ } }
  }

  // one poll: true once a new moth line is shown. session: only moth's reactions to it; null: any line (/moth's
  // reply, which comes back untagged)
  async function refresh(display, session) {
    if (cursor === null) { start(await getSays(1e9)); return false; }
    const d = await getSays(cursor, epoch, session);
    cursor = d.next; epoch = d.epoch;
    const says = saysOf(d.events);
    if (says.length) display(says[says.length - 1]);
    return says.length > 0;
  }

  function watch(ctx, display = (t) => widget(ctx, t), session = null) {
    if (!ctx || !ctx.hasUI) return;
    const mine = ++run, until = Date.now() + WAIT_MS;
    const step = async () => {
      let done = false;
      try { done = await refresh(display, session); } catch (e) { /* moth asleep: keep trying until the window ends */ }
      if (!done && mine === run && Date.now() < until) { const t = setTimeout(step, 500); t.unref?.(); }
    };
    const t = setTimeout(step, 300); t.unref?.();
  }

  pi.on("agent_start", (event, ctx) => {
    last = "";
    const on = enabled();
    if (on && !wasOn) { cursor = null; epoch = null; }   // just turned on: never resume a cursor from the off time
    wasOn = on;
    if (ctx && ctx.hasUI && on) baseline();
  });
  pi.on("agent_end", (event) => {
    try { const t = lastText(event && event.messages); if (t) last = t; } catch (e) { /* fail open */ }
  });
  pi.on("agent_settled", (event, ctx) => {
    try {
      const t = last; last = "";
      if (t && !(event && event.aborted)) {
        let session = "";
        try { session = ctx.sessionManager.getSessionId() || ""; } catch (e) { /* older Pi or no ctx */ }
        post(t, session, labelOf(ctx && ctx.cwd, session));   // always: the pet reacts even with the display off
        if (!enabled()) { if (ctx) quiet(ctx); }
        else if (session) watch(ctx, undefined, session);   // no id: no way to tell our reaction from another's
      }
    } catch (e) { /* fail open */ }
  });

  try {
    pi.registerCommand?.("moth", {
      description: "Say something to moth, your tiny companion (answers even with show_in_harness off)",
      handler: async (args, ctx) => {
        const text = String(args || "").trim();
        if (!text) return ctx.ui.notify("usage: /moth <something to tell moth>", "info");
        const on = enabled();   // off: answer with a one-off notice, no widget left behind
        const note = (reply) => ctx.ui.notify(`moth> ${String(reply).replace(ANSI, "")}`, "info");
        try {
          const r = await fetch(`${BASE}/api/chat`, {
            method: "POST", headers: headers(), body: JSON.stringify({ text }),
            signal: AbortSignal.timeout(WAIT_MS),
          });
          const d = await r.json();
          if (!r.ok) return ctx.ui.notify(`moth didn't take that: ${d && d.error}`, "info");   // e.g. no token yet
          const reply = saysOf(d.events).join(" ") || "...";
          if (!(on && widget(ctx, reply))) note(reply);
        } catch (e) {
          const slow = e && (e.name === "TimeoutError" || e.name === "AbortError");
          ctx.ui.notify(slow ? "moth is still thinking..." : "moth is asleep (start it: python -m moth.serve)", "info");
          if (slow) on ? watch(ctx) : watch(ctx, note);
        }
      },
    });
  } catch (e) { /* older Pi: the poster above still works */ }
}
